30	namespace trt_edgellm
31	{
32	namespace rt
33	{
34	DecoderRegistry::DecoderRegistry(DecodingRuntimeContext& runtime, DecoderRegistryConfig const& config)
35	    : mDefaultDecoder(std::make_unique<VanillaDecoder>(runtime))
36	{
37	    if (config.draftingConfig.has_value())
38	    {
39	        switch (runtime.deployment.specDecodeMode())
40	        {
41	        case SpecDecodeMode::kMTP:
42	            mSpeculativeDecoder
43	                = std::make_unique<MTPDecoder>(runtime, config.engineDir, *config.draftingConfig, config.stream);
44	            break;
45	        case SpecDecodeMode::kEAGLE:
46	            mSpeculativeDecoder
47	                = std::make_unique<EagleDecoder>(runtime, config.engineDir, *config.draftingConfig, config.stream);
48	            break;
49	        case SpecDecodeMode::kDFlash:
50	            mSpeculativeDecoder
51	                = std::make_unique<DFlashDecoder>(runtime, config.engineDir, *config.draftingConfig, config.stream);
52	            break;
53	        case SpecDecodeMode::kGemma4MTP:
54	            mSpeculativeDecoder
55	                = std::make_unique<Gemma4MTPDecoder>(runtime, config.engineDir, *config.draftingConfig, config.stream);
56	            break;
57	        case SpecDecodeMode::kNONE:
58	            throw std::runtime_error("SpecDecode drafting config was set but no mode is active.");
59	        }
60	        LOG_INFO("Selected %s decoding strategy.", mSpeculativeDecoder->name());
61	    }
62	}
63	
64	DecodingStrategy& DecoderRegistry::select(LLMGenerationRequest const& request) const noexcept
65	{
66	    if (!mSpeculativeDecoder || request.disableSpecDecode)
67	    {
68	        return *mDefaultDecoder;
69	    }
70	
71	    return *mSpeculativeDecoder;
72	}
73	
74	DecodingStrategy& DecoderRegistry::cachePrimingStrategy() const noexcept
75	{
76	    return mSpeculativeDecoder ? *mSpeculativeDecoder : *mDefaultDecoder;
77	}
78	
79	bool DecoderRegistry::captureCudaGraphs(cudaStream_t stream) const
80	{
81	    bool const skipDefaultCapture = mSpeculativeDecoder && mSpeculativeDecoder->kind() == DecodingStrategyKind::kDFlash;
82	    if (skipDefaultCapture)
83	    {
84	        LOG_INFO("Skipping vanilla CUDA graph capture for DFlash speculative runtime.");
85	    }
86	    bool const defaultCaptureStatus
87	        = (!skipDefaultCapture && mDefaultDecoder) ? mDefaultDecoder->captureCudaGraphs(stream) : true;
88	    bool const speculativeCaptureStatus = mSpeculativeDecoder ? mSpeculativeDecoder->captureCudaGraphs(stream) : true;
89	    bool const captureStatus = defaultCaptureStatus && speculativeCaptureStatus;
90	    if (captureStatus)
91	    {
92	        LOG_INFO("Successfully captured decoding CUDA graphs for active decoding strategies.");
93	    }
94	    else
95	    {
96	        LOG_WARNING(
97	            "Failed to capture decoding CUDA graphs for some stages. The inference can proceed without "
98	            "CUDA graph capture, but at cost of performance degradation.");
99	    }
100	    return captureStatus;
101	}
102	
103	int64_t DecoderRegistry::getRequiredContextMemorySize() const noexcept
104	{
105	    int64_t const defaultContextMemory = mDefaultDecoder ? mDefaultDecoder->getRequiredContextMemorySize() : 0;
106	    int64_t const speculativeContextMemory
107	        = mSpeculativeDecoder ? mSpeculativeDecoder->getRequiredContextMemorySize() : 0;
108	    return std::max(defaultContextMemory, speculativeContextMemory);
109	}
