135	bool MTPDecoder::decodeStep(DecodingInferenceContext& context)
136	{
137	    if (context.generationRound == 0)
138	    {
139	        if (!runDraftModelPrefill(context))
140	        {
141	            LOG_ERROR("Failed to execute prefill step for draft model.");
142	            return false;
143	        }
144	    }
145	    else if (!runDraftModelAcceptToken(context))
146	    {
147	        LOG_ERROR("Failed to execute accept token step for draft model.");
148	        return false;
149	    }
150	
151	    if (!constructDraftProposal(context))
152	    {
153	        LOG_ERROR("Failed to construct draft proposal.");
154	        return false;
155	    }
156	
157	    if (!runBaseModelVerification(context))
158	    {
159	        LOG_ERROR("Failed to verify draft proposal with base model.");
160	        return false;
161	    }
162	    return true;
163	}
