165	bool MTPDecoder::runDraftModelPrefill(DecodingInferenceContext& context)
166	{
167	    assert(mDraftExecutor != nullptr);
168	    assert(mRuntime.deployment.specConfig.has_value());
169	    assert(mRuntime.deployment.draft.has_value());
170	    TIME_STAGE(metrics::StageNames::kSPEC_DECODE_DRAFT_PREFILL, context.stream);
171	    NVTX_SCOPED_RANGE(nvtx_draft_prefill,
172	        ("SPEC_DECODE_DRAFT_PREFILL[R" + std::to_string(context.generationRound) + ","
173	            + std::to_string(context.activeBatchSize) + "]")
174	            .c_str(),
175	        nvtx_colors::DARK_ORANGE);
176	
177	    int32_t const activeBatchSize = context.activeBatchSize;
178	    int32_t const draftHiddenSize = mRuntime.deployment.specConfig->draftHiddenSize;
179	    int32_t const draftVocabSize = mRuntime.deployment.draft->outputVocabSize;
180	    int32_t const inputIdsLength
181	        = *std::max_element(context.effectivePrefillLengths.begin(), context.effectivePrefillLengths.end());
182	
183	    check::check(mRuntime.base.pipelineIO.baseHiddenStates.getShape()[0] == activeBatchSize
184	            && mRuntime.base.pipelineIO.baseHiddenStates.getShape()[1] == inputIdsLength,
185	        "BaseHiddenStates shape [batch, seq_len, hidden_dim] shall match active prefill shape.");
186	
187	    check::check(mRuntime.preprocess.idsInput.reshape({activeBatchSize, inputIdsLength}), "Tensor reshape failed");
188	    check::check(
189	        mRuntime.base.pipelineIO.draftHiddenStatesIn.reshape({activeBatchSize, inputIdsLength, draftHiddenSize}),
190	        "Tensor reshape failed");
191	    check::check(
192	        mRuntime.base.pipelineIO.outputLogits.reshape({activeBatchSize, draftVocabSize}), "Tensor reshape failed");
193	    check::check(mRuntime.base.pipelineIO.draftHiddenStatesOut.reshape({activeBatchSize, draftHiddenSize}),
