    int32_t const verifySize = draftingStep + 1;
    int32_t const baseHiddenSize = mRuntime.deployment.specConfig->baseOutputHiddenDim;
    int32_t const draftVocabSize = mRuntime.deployment.draft->outputVocabSize;

